import{_ as i,b as r,c as l,g as n}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"概率推理","description":"","frontmatter":{"title":"概率推理","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach/13.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach/13.md"}'),o={name:"articles/artificial-intelligence/books/AI-modern-approach/13.md"};function s(e,t,a,g,d,P){return r(),l("div",null,[...t[0]||(t[0]=[n('<p>第 13 章标志着从确定性逻辑世界转向不确定性推理。核心内容包括：</p><h2 id="概率基本概念" tabindex="-1">概率基本概念</h2><ul><li><strong>概率公理</strong>：0 ≤ P(A) ≤ 1、P(true) = 1、P(Ω) = 1、可加性</li><li><strong>无条件概率（先验）</strong>、<strong>条件概率</strong>：P(A|B) = P(A∧B) / P(B)</li><li><strong>概率的合取规则</strong>：P(A∧B) = P(A) P(B|A)</li></ul><h2 id="贝叶斯规则" tabindex="-1">贝叶斯规则</h2><p>P(A|B) = P(B|A) P(A) / P(B)</p><p>常用于因果推理（已知原因求结果）与诊断推理（已知结果求原因）的转换。</p><h2 id="随机变量与联合分布" tabindex="-1">随机变量与联合分布</h2><ul><li>随机变量分为离散、连续（本章主要离散）</li><li><strong>联合概率分布表</strong>：所有变量取值的概率总和为 1</li><li><strong>边缘化</strong>（求和消元）、<strong>归一化</strong></li></ul><h2 id="独立性" tabindex="-1">独立性</h2><ul><li><strong>绝对独立</strong>：P(A∧B) = P(A) P(B) 或 P(A|B) = P(A)</li><li><strong>条件独立</strong>：给定 C，A 与 B 独立：P(A∧B|C) = P(A|C) P(B|C)</li><li>条件独立是贝叶斯网络的基础</li></ul><h2 id="期望与方差" tabindex="-1">期望与方差</h2><ul><li><strong>期望</strong>：E[X] = Σᵢ xᵢ P(X = xᵢ)</li><li><strong>方差</strong>：Var(X) = E[(X - μ)²]</li></ul><h2 id="推理方法" tabindex="-1">推理方法</h2><ul><li><strong>枚举推理</strong>：用联合分布计算后验概率，复杂度指数级</li><li><strong>拒绝采样</strong>（简单介绍，后续章节详述）</li></ul><p>本章重点是掌握概率语言及其在 AI 中的应用，为后续贝叶斯网络、MDP、强化学习打下基础。</p>',15)])])}const A=i(o,[["render",s]]);export{p as __pageData,A as default};
